var payload = msg.payload;

// Try to parse JSON if it's a string
if (typeof payload === 'string') {
    try {
        payload = JSON.parse(payload);
    } catch(e) {
        // Not valid JSON, wrap it
        var topicParts = msg.topic.split('/');
        var camId = topicParts[topicParts.length - 1];
        payload = {
            event: "UNKNOWN_EVENT",
            camera: camId,
            raw: msg.payload,
            timestamp: new Date().toISOString()
        };
    }
}

msg.payload = payload;
return msg;

let data = JSON.parse(msg.payload)
let msgArr = [null, null]
//单设备数据状态变化自动上报
if (data.agtid && data.chg && Array.isArray(data.chg)) {

    //构建上报数据结构
    let finalStatus = {}
    let storageDevices = flow.get("storageDevices")
    let storageDevicesObj = {}
    if (storageDevices && storageDevices[data.agtid] && storageDevices[data.agtid].layer && storageDevices[data.agtid].gateway && storageDevices[data.agtid].devices) {
        let devices = storageDevices[data.agtid].devices
        let gateway = storageDevices[data.agtid].gateway
        let layer = storageDevices[data.agtid].layer
        for (let i = 0; i < devices.length; i++) {
            let d = devices[i]
            d.gateway = gateway
            d.layer = layer
            storageDevicesObj[d.code] = d
        }
    }

    let lifesmartDeviceStatus = flow.get("lifesmartDeviceStatus")
    if (!lifesmartDeviceStatus) {
        lifesmartDeviceStatus = {}
    }
    let localStatus = lifesmartDeviceStatus[data.agtid]
    if (!localStatus || localStatus == undefined){
        return
    }
    let items = data.chg
    for (let i = 0; i < items.length; i++) {

        //环境传感器
        if (items[i].devtype == "SL_SC_BE") {
            if (items[i].T) {
                localStatus[items[i].me + "_T"].temperature = items[i].T.v
            }
            if (items[i].H) {
                localStatus[items[i].me + "_T"].humidity = items[i].H.v
            }
            if (items[i].Z) {
                localStatus[items[i].me + "_T"].light = items[i].Z.v
            }
            if (items[i].V) {
                localStatus[items[i].me + "_T"].charge = items[i].V.v
            }

            let code = data.agtid + "_" + items[i].me + "_T"
            if (storageDevicesObj[code]) {
                finalStatus[code] = {}
                finalStatus[code].status = localStatus[items[i].me + "_T"]
                finalStatus[code].code = code
                finalStatus[code].gateway = storageDevicesObj[code].gateway
                finalStatus[code].layer = storageDevicesObj[code].layer
            }

        } else if (items[i].devtype == "SL_UACCB") {
            if (items[i].T) {
                localStatus[items[i].me + "_O"].temperature = items[i].T.v
            }
            if (items[i].tT) {
                localStatus[items[i].me + "_O"].pretemperature = items[i].tT.v
            }
            if (items[i].MODE) {
                localStatus[items[i].me + "_O"].mode = items[i].MODE.v
            }
            if (items[i].F) {
                if (items[i].F.v < 30) {
                    localStatus[items[i].me + "_O"].fan = 15
                } else if (items[i].F.v >= 30 && items[i].F.v < 65) {
                    localStatus[items[i].me + "_O"].fan = 45
                } else {
                    localStatus[items[i].me + "_O"].fan = 75
                }
            }
            if (items[i].O) {
                localStatus[items[i].me + "_O"].status = items[i].O.v === 1 ? 'on' : 'off'
            }
            if (items[i].ALM) {
                localStatus[items[i].me + "_O"].alarmValue = items[i].ALM.v
                if (items[i].ALM.v === 0) {
                    localStatus[items[i].me + "_O"].alarm = "normal"
                } else {
                    localStatus[items[i].me + "_O"].alarm = "alarm"
                }
            }

            let code = data.agtid + "_" + items[i].me + "_O"
            if (storageDevicesObj[code]) {
                finalStatus[code] = {}
                finalStatus[code].status = localStatus[items[i].me + "_O"]
                finalStatus[code].code = code
                finalStatus[code].gateway = storageDevicesObj[code].gateway
                finalStatus[code].layer = storageDevicesObj[code].layer
            }
        } else if (items[i].devtype == "SL_FCU") {
