// 部署节点后，此处添加的代码将运行一次。 
let getBroadcastAddress = function () {
    const broadcastAddress = new Set(); // 使用Set来保存广播地址可以自动去重
    let interfaces = os.networkInterfaces();
    // 遍历获取需要的网络接口信息
    for (const key in interfaces) {
        for (const interface of interfaces[key]) {
            // 该接口是IPv4，且不是内部回环地址（对于IPv4而言回环地址为127.0.0.1）
            if (interface.family === 'IPv4' && !interface.internal && interface.address !== '127.0.0.1') {
                // 将IP地址和子网掩码各自切成四个字段，方便下面计算广播地址
                let slices = [interface.address.split('.'), interface.netmask.split('.')];
                let fields = [];
                for (let i = 0; i < 4; i++) {
                    // 广播地址 = IP | (~MASK)
                    fields[i] = String(Number(slices[0][i]) | ((~Number(slices[1][i])) & 0xff));
                }
                // 拼合广播地址为字符串形式并存入Set
                broadcastAddress.add(`${fields[0]}.${fields[1]}.${fields[2]}.${fields[3]}`);
            }
        }
    }
    return broadcastAddress;
}
flow.set("getBroadcastAddress", getBroadcastAddress)

//获取指定网关下的设备
let getDeviceLocal = function (gateway, me) {
    let storageDevices = flow.get("devices")
    if (!storageDevices) {
        storageDevices = {}
    }
    if (!storageDevices[gateway]) {
        return false
    }
    let devices = storageDevices[gateway]
    for (let i = 0; i < devices.length; i++) {
        if (devices[i].me == me) {
            return devices[i]
        }
    }
    return false
}
flow.set("getDeviceLocal", getDeviceLocal)

//获取指定网关IP
let getGatewayIPLocal = function (gateway) {
    let gateways = flow.get("gateways")
    if (!gateways) {
        gateways = {}
    }
    if (!gateways[gateway] || !gateways[gateway].ip) {
        return false
    }

    return gateways[gateway].ip
}
flow.set("getGatewayIPLocal", getGatewayIPLocal)

//获取单个设备控制信息
let getControlDeviceLocal = function (type, id, status, param) {
    let id_arr = id.split("_")
    let me = id_arr[id_arr.length - 2]
    let idx = id_arr[id_arr.length - 1]
    let agtId = id.substring(0, id.indexOf("_" + me + "_" + idx))
    // if (type == "blind" || type == "pscreen" || type == "airconditioning" || type == "air") {
    //     me = id_arr[id_arr.length - 1]
    //     agtId = id.substring(0, id.indexOf("_" + me))
    // }

    let ip = flow.get("getGatewayIPLocal")(agtId)
    if (!ip) {
        return false
    }
    let device = flow.get("getDeviceLocal")(agtId, me)

    if (!device) {
        return false
    }

    let vtype = 128
    let vval = 0
    if (status == "open" || type == "door" || type == "blind" || type == "pscreen") {
        vtype = 129
        vval = 1
    }
    if (type == "blind" || type == "pscreen") {
        if (device['devtype'] == "SL_P") {
            if (param && param.isRevert == 1) {
                if (status == "open") {
                    idx = "P3"
                } else if (status == "close") {
                    idx = "P2"
                } else {
                    idx = "P4"
                }
            } else {
                if (status == "open") {
                    idx = "P2"
                } else if (status == "close") {
                    idx = "P3"
                } else {
                    idx = "P4"
                }
            }
        } else if (device['devtype'] == "SL_DOOYA") {
            idx = "P2"
            if (param && param.isRevert == 1) {
                if (status == "open") {
                    idx = "CL"
                    vtype = 0xCF
                    vval = 0
                } else if (status == "close") {
                    idx = "OP"
                    vtype = 0xCF
                    vval = 100
                } else {
                    idx = "ST"
                    vtype = 0xCF
                    vval = 0x80
                }
            } else {
                if (status == "open") {
                    idx = "OP"
                    vtype = 0xCF
                    vval = 100
                } else if (status == "close") {
                    idx = "CL"
                    vtype = 0xCF
                    vval = 0
                } else {
                    idx = "ST"
                    vtype = 0xCF
                    vval = 0x80
                }
            }
        } else {
            if (param && param.isRevert == 1) {
                if (status == "open") {
                    idx = "CL"
                } else if (status == "close") {
                    idx = "OP"
                } else {
                    idx = "ST"
                }
            } else {
                if (status == "open") {
                    idx = "OP"
                } else if (status == "close") {
                    idx = "CL"
                } else {
                    idx = "ST"
                }
            }
        }
    } else if (type == "airconditioning" || type == "air") {
        if (device['devtype'] == "SL_CP_AIR") {
            idx = "P1"
        } else if (device['devtype'] == "SL_NATURE") {
            idx = "L1"
        } else if (device['devtype'] == "SL_FCU") {
            idx = "O"
        } else if (device['devtype'] == "SL_UACCB") {
            idx = "O"
        } else if (device['devtype'] == "SL_FCU") {
            idx = "O"
        } else if (device['devtype'].indexOf("V_FRESH_P") != -1) {
            idx = "O"
            me = id.split("#")[1]
        } else if (device['devtype'].indexOf("V_AIR_P") != -1) {
            idx = "O"
            me = id.split("#")[1]
        }
    }

    let control = {
        agtId: agtId,
        ip: ip,
        args: [{
            tag: "geeqee",
            me: me,
            idx: idx,
            type: vtype,
            val: vval
        }]
    }
    if (device['fulltype'] == "SL_NATURE_V3" || device['fulltype'] == "SL_FCU_V1") {
        if (status == "open" && param.temperature) {
            control.args.push({
                tag: "geeqee",
                me: me,
                idx: "P8",
                type: 0x88,
                val: parseInt(param.temperature) * 10
            })
        }
        if (status == "open" && param.mode) {
            control.args.push({
                tag: "geeqee",
                me: me,
                idx: "P7",
                type: 0xCE,
                val: parseInt(param.mode)
            })
        }
        if (status == "open" && param.fan) {
            control.args.push({
                tag: "geeqee",
                me: me,
                idx: "P9",
                type: 0xCE,
                val: parseInt(param.fan)
            })
        }
    } else if (device['fulltype'] == "SL_UACCB") {
        if (status == "open" && param.temperature) {
            control.args.push({
                tag: "geeqee",
                me: me,
                idx: "tT",
                type: 0x88,
                val: parseInt(param.temperature) * 10
            })
        }
        if (status == "open" && param.mode) {
            control.args.push({
                tag: "geeqee",
                me: me,
                idx: "MODE",
                type: 0xCE,
                val: parseInt(param.mode)
            })
        }
        if (status == "open" && param.fan) {
            control.args.push({
                tag: "geeqee",
                me: me,
                idx: "F",
                type: 0xCE,
                val: parseInt(param.fan)
            })
        }
    }
    return control
}
