    let addrObj = {}
    for(let i = 0; i < devices.length; i++){
        let codeArr = devices[i].code.split("-")
        let unitid = parseInt(codeArr[1])
        if(addrObj[unitid] == undefined){
            addrObj[unitid] = []
        }
        let address = parseInt(codeArr[2])
        addrObj[unitid].push(address)
    }

    let controlArr = []
    Object.keys(addrObj).forEach(function (unitid) {
        addrObj[unitid].sort(function(a,b){return a > b;})
        let sortArr = addrObj[unitid]
        if(sortArr.length > 0){
            let item = {}
            item.unitid = unitid
            item.status = []
            item.quantity = 1
            item.address = sortArr[0]
            for(let i = 0; i < sortArr.length; i++){
                if(sortArr[i+1] == undefined){
                    item.status = Array(item.quantity).fill(status[0])
                    controlArr.push(JSON.parse(JSON.stringify(item)))
                }else if(sortArr[i+1] - 1 == sortArr[i]){
                    ++item.quantity
                }else{
                    item.status = Array(item.quantity).fill(status[0])
                    controlArr.push(JSON.parse(JSON.stringify(item)))
                    item.quantity = 1
                    item.address = sortArr[i+1]
                }
            }
        }

    });
    msg.payload = controlArr
    node.send(msg)
}

